/* Original protocol reader for Android FrameTimeline and the SurfaceFlinger latency interface.
 * Wire fields follow AOSP Android 16 frame_timeline_event.proto; no Scene code or binary is linked. */
#include <sys/wait.h>
#include <poll.h>
#define FRAME_LAYERS 64
#define FRAME_SLOTS 4096
typedef struct {U64 cookie,token,display,start,end;int kind,layer,present,jank,prediction;unsigned seq;} FrameSpan;
typedef struct {U64 token,present;int type;} DisplayFrame;
typedef struct {U64 token;int layer;double duration;} ExpectedFrame;
typedef struct {int pid;U64 start,last;char package[161];} FramePid;
typedef struct {int pid,source;U64 hash,processStart,first,last,lastDisplay;char name[193];unsigned presented,jank,classified,dropped,workCount,intervalCount,work[1001],interval[1001],bins[601],bad[601],known[601];} FrameLayer;
static struct {U64 began,ended,lastPacket;long offset;int tracePid,frameRows,nlayers,npids,loss,capped,events;char selection[161],trace[512];FrameSpan spans[FRAME_SLOTS];DisplayFrame displays[FRAME_SLOTS];ExpectedFrame expected[FRAME_SLOTS];FramePid pids[128];FrameLayer layers[FRAME_LAYERS];FILE *csv;} frames;
typedef struct {const unsigned char *p,*end;unsigned field,wire;U64 value;const unsigned char *bytes;size_t size;} Proto;
static U64 bootns(void){struct timespec t;clock_gettime(CLOCK_BOOTTIME,&t);return (U64)t.tv_sec*1000000000ULL+t.tv_nsec;}
static int varint(const unsigned char **p,const unsigned char *end,U64 *v){*v=0;for(int n=0;n<10&&*p<end;n++){unsigned b=*(*p)++;if(n==9&&b>1)return 0;*v|=(U64)(b&127)<<(7*n);if(!(b&128))return 1;}return 0;}
static int proto(Proto *r){U64 key,len;if(r->p>=r->end||!varint(&r->p,r->end,&key)||!key)return 0;r->field=key>>3;r->wire=key&7;r->bytes=NULL;r->size=0;if(r->wire==0)return varint(&r->p,r->end,&r->value);if(r->wire==2){if(!varint(&r->p,r->end,&len)||len>(U64)(r->end-r->p))return 0;r->bytes=r->p;r->size=(size_t)len;r->p+=len;return 1;}size_t skip=r->wire==1?8:r->wire==5?4:0;if(!skip||skip>(size_t)(r->end-r->p))return 0;r->p+=skip;return 1;}
static U64 namehash(const unsigned char *s,size_t len){U64 h=1469598103934665603ULL;for(size_t i=0;i<len;i++)h=(h^s[i])*1099511628211ULL;return h;}
static void framepid(int pid,int app,U64 start){if(app<0||strcmp(apps[app].package,frames.selection))return;for(int i=0;i<frames.npids;i++)if(frames.pids[i].pid==pid&&frames.pids[i].start==start){frames.pids[i].last=bootns();return;}if(frames.npids>=128){frames.loss=1;return;}FramePid *p=&frames.pids[frames.npids++];p->pid=pid;p->start=start;p->last=bootns();snprintf(p->package,sizeof p->package,"%s",apps[app].package);}
static U64 frameidentity(int pid,U64 ns){long hz=sysconf(_SC_CLK_TCK);for(int i=frames.npids-1;i>=0;i--){FramePid *p=&frames.pids[i];if(p->pid==pid&&ns>=p->start*1000000000ULL/(U64)hz&&ns<=p->last+2000000000ULL)return p->start;}return 0;}
static int framelayer(int pid,U64 identity,const unsigned char *name,size_t len,int source){U64 hash=namehash(name,len);for(int i=0;i<frames.nlayers;i++)if(frames.layers[i].pid==pid&&frames.layers[i].processStart==identity&&frames.layers[i].hash==hash&&frames.layers[i].source==source)return i;if(frames.nlayers>=FRAME_LAYERS){frames.loss=1;return -1;}int index=frames.nlayers++;FrameLayer *l=&frames.layers[index];l->pid=pid;l->processStart=identity;l->hash=hash;l->source=source;size_t copy=len<sizeof l->name-1?len:sizeof l->name-1;memcpy(l->name,name,copy);l->name[copy]=0;safe(l->name);return index;}
static void framewrite(FrameSpan *s,U64 present){if(s->layer<0||s->layer>=frames.nlayers||s->end<s->start||s->start<frames.began||(frames.ended&&(s->end>frames.ended||present>frames.ended)))return;FrameLayer *l=&frames.layers[s->layer];double work=l->source==1&&s->present!=4&&s->prediction==1?(s->end-s->start)/1e6:-1,expected=-1,interval=-1;ExpectedFrame *e=&frames.expected[(s->token^(U64)s->layer*37)%FRAME_SLOTS];if(e->token==s->token&&e->layer==s->layer)expected=e->duration;if(work>=0&&work<10000){l->work[(int)(work*10)>1000?1000:(int)(work*10)]++;l->workCount++;}if(s->jank>0){l->classified++;if(s->jank!=1)l->jank++;}if(s->present==4)l->dropped++;
    if(present>=frames.began&&s->present>=1&&s->present<=3&&(!l->last||present>l->last)){unsigned bin=(unsigned)((present-frames.began)/1000000000ULL);if(!l->first)l->first=present;if(l->last){interval=(present-l->last)/1e6;l->interval[interval>1000?1000:(int)interval]++;l->intervalCount++;}l->last=present;l->lastDisplay=s->display;l->presented++;if(bin<=600){l->bins[bin]++;if(s->jank>0){l->known[bin]++;if(s->jank!=1)l->bad[bin]++;}}}
    if(frames.csv&&frames.frameRows<200000){double at=present>=frames.began?(present-frames.began)/1e6:(s->end-frames.began)/1e6;fprintf(frames.csv,"%.3f,%d,%d,%llu,%llu,%llu,%.3f,%.3f,%.3f,%d,%d\n",at,s->layer,s->kind==2?0:l->pid,s->token,s->display,present,interval,work,expected,s->jank,s->present);frames.frameRows++;}else if(frames.csv)frames.capped=1;
}
static void framejoins(void){for(int i=0;i<FRAME_SLOTS;i++){FrameSpan *s=&frames.spans[i];if(s->kind!=4||!s->end)continue;if(s->present==4){framewrite(s,0);s->kind=0;continue;}DisplayFrame *d=&frames.displays[s->display%FRAME_SLOTS];if(d->token==s->display&&d->present){framewrite(s,d->type>=1&&d->type<=3?d->present:0);s->kind=0;}}}
static void frameevent(const unsigned char *data,size_t len,U64 ns,unsigned seq){Proto event={.p=data,.end=data+len};while(proto(&event)){if(event.wire!=2||event.field<2||event.field>5)continue;Proto r={.p=event.bytes,.end=event.bytes+event.size};FrameSpan s={.start=ns,.kind=(int)event.field,.layer=-1,.seq=seq,.jank=-1};int pid=0,buffer=1,hascookie=0;const unsigned char *name=NULL;size_t namesize=0;while(proto(&r)){if(r.wire==0){if(r.field==1){s.cookie=r.value;hascookie=1;}if(r.field==2)s.token=r.value;if(s.kind==2){if(r.field==4)s.present=(int)r.value;}else if(s.kind==3||s.kind==4){if(r.field==3)s.display=r.value;if(r.field==4)pid=(int)r.value;if(r.field==6)s.present=(int)r.value;if(r.field==9)s.jank=(int)r.value;if(r.field==10)s.prediction=(int)r.value;if(r.field==11)buffer=(int)r.value;}}else if(r.wire==2&&r.field==5){name=r.bytes;namesize=r.size;}}if(!hascookie)continue;FrameSpan *slot=&frames.spans[s.cookie%FRAME_SLOTS];if(s.kind==5){if(slot->cookie!=s.cookie||slot->seq!=seq||!slot->kind)continue;slot->end=ns;if(slot->kind==2){DisplayFrame *d=&frames.displays[slot->token%FRAME_SLOTS];d->token=slot->token;d->present=ns;d->type=slot->present;slot->kind=0;}else if(slot->kind==3){ExpectedFrame *e=&frames.expected[(slot->token^(U64)slot->layer*37)%FRAME_SLOTS];e->token=slot->token;e->layer=slot->layer;e->duration=ns>=slot->start?(ns-slot->start)/1e6:-1;slot->kind=0;}else if(slot->kind==4){DisplayFrame *d=&frames.displays[slot->display%FRAME_SLOTS];if(slot->present==4||(d->token==slot->display&&d->present)){framewrite(slot,slot->present==4||d->type<1||d->type>3?0:d->present);slot->kind=0;}}continue;}
        if(s.kind!=2){U64 identity=frameidentity(pid,ns);if(!identity||!name||!buffer)continue;s.layer=framelayer(pid,identity,name,namesize,1);if(s.layer<0)continue;}if(slot->kind)frames.loss=1;*slot=s;}}
static void framepacket(const unsigned char *data,size_t len){Proto p={.p=data,.end=data+len};U64 ns=0;unsigned seq=0,clock=6;const unsigned char *event=NULL;size_t size=0;while(proto(&p)){if(p.wire==0){if(p.field==8)ns=p.value;if(p.field==10)seq=(unsigned)p.value;if(p.field==58)clock=(unsigned)p.value;if(p.field==42&&p.value)frames.loss=1;}else if(p.wire==2&&p.field==76){event=p.bytes;size=p.size;}}if(event&&ns&&clock==6){frames.events++;if(ns>frames.lastPacket)frames.lastPacket=ns;frameevent(event,size,ns,seq);}}
static void framepoll(void){char file[512];snprintf(file,sizeof file,"%s",frames.trace);FILE *f=fopen(file,"rb");if(!f)return;if(fseek(f,frames.offset,SEEK_SET)){fclose(f);return;}for(int packets=0;packets<20000;packets++){long before=ftell(f);unsigned char head[11];U64 size=0;int first=fgetc(f);if(first==EOF)break;if(first!=10){frames.loss=1;break;}int bytes=0;for(;bytes<10;bytes++){int c=fgetc(f);if(c==EOF)break;head[bytes]=(unsigned char)c;if(!(c&128)){bytes++;break;}}const unsigned char *p=head;if(bytes==0||!varint(&p,head+bytes,&size)||size>262144){fseek(f,before,SEEK_SET);break;}unsigned char *packet=malloc((size_t)size? (size_t)size:1);if(!packet)break;if(fread(packet,1,(size_t)size,f)!=(size_t)size){free(packet);fseek(f,before,SEEK_SET);break;}framepacket(packet,(size_t)size);free(packet);frames.offset=ftell(f);}fclose(f);framejoins();if(frames.csv)fflush(frames.csv);}
static double framequantile(unsigned *hist,unsigned count,double q,double unit){if(!count)return -1;unsigned goal=(unsigned)(count*q+0.999999),sum=0;for(int i=0;i<=1000;i++){sum+=hist[i];if(sum>=goal)return i*unit;}return 1000*unit;}
static void framesummary(void){char file[512],temp[512];path(file,sizeof file,"record.layers.tsv");path(temp,sizeof temp,"record.layers.tmp");FILE *f=fopen(temp,"w");if(!f)return;fputs("id\tpid\tsource\tname\tpresented\tjank\tclassified\tdropped\taverageFps\tp95IntervalMs\tp99IntervalMs\tp95WorkMs\tp99WorkMs\n",f);for(int i=0;i<frames.nlayers;i++){FrameLayer *l=&frames.layers[i];double fps=l->presented>1&&l->last>l->first?(l->presented-1)*1e9/(l->last-l->first):-1;fprintf(f,"%d\t%d\t%s\t%s\t%u\t%u\t%u\t%u\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\n",i,l->pid,l->source==1?"frametimeline":"surfaceflinger-latency",l->name,l->presented,l->jank,l->classified,l->dropped,fps,framequantile(l->interval,l->intervalCount,.95,1),framequantile(l->interval,l->intervalCount,.99,1),framequantile(l->work,l->workCount,.95,.1),framequantile(l->work,l->workCount,.99,.1));}fclose(f);rename(temp,file);
    path(file,sizeof file,"record.frame-bins.tsv");path(temp,sizeof temp,"record.frame-bins.tmp");f=fopen(temp,"w");if(f){fputs("second\tlayer\tpresented\tjank\tclassified\n",f);for(int i=0;i<frames.nlayers;i++)for(int j=0;j<=600;j++)if(frames.layers[i].bins[j])fprintf(f,"%d\t%d\t%u\t%u\t%u\n",j,i,frames.layers[i].bins[j],frames.layers[i].bad[j],frames.layers[i].known[j]);fclose(f);rename(temp,file);}path(file,sizeof file,"record.frames.state");path(temp,sizeof temp,"record.frames.tmp");f=fopen(temp,"w");if(f){fprintf(f,"%d\t%d\t%d\t%d\t%llu\n",frames.tracePid>0,frames.events,frames.loss,frames.capped,frames.lastPacket>=frames.began?(frames.lastPacket-frames.began)/1000000ULL:0);fclose(f);rename(temp,file);}}
static int framecommand(char *out,size_t size,const char *arg,const char *layer){int pipes[2];if(pipe(pipes))return 0;pid_t child=fork();if(!child){dup2(pipes[1],STDOUT_FILENO);int null=open("/dev/null",O_WRONLY);if(null>=0)dup2(null,STDERR_FILENO);close(pipes[0]);close(pipes[1]);if(layer)execl("/system/bin/dumpsys","dumpsys","-t","1","SurfaceFlinger",arg,layer,(char*)NULL);else execl("/system/bin/dumpsys","dumpsys","-t","1","SurfaceFlinger",arg,(char*)NULL);_exit(127);}close(pipes[1]);if(child<0){close(pipes[0]);return 0;}fcntl(pipes[0],F_SETFL,O_NONBLOCK);size_t used=0;double until=clocknow()+.35;int finished=0;while(clocknow()<until&&!stopped){struct pollfd fd={.fd=pipes[0],.events=POLLIN};poll(&fd,1,20);ssize_t n=read(pipes[0],out+used,size-used-1);if(n>0){used+=(size_t)n;if(used>=size-1)break;}if(waitpid(child,NULL,WNOHANG)==child){finished=1;while((n=read(pipes[0],out+used,size-used-1))>0){used+=(size_t)n;if(used>=size-1)break;}break;}}if(!finished){kill(child,SIGKILL);waitpid(child,NULL,0);}close(pipes[0]);out[used]=0;return finished&&used>0;}
static int framecompare(const void *a,const void *b){U64 x=*(const U64*)a,y=*(const U64*)b;return x<y?-1:x>y?1:0;}
static void framelatency(void){char list[16384];if(!framecommand(list,sizeof list,"--list",NULL))return;char *names[256];int nnames=0,tested=0;char *save=NULL;for(char *name=strtok_r(list,"\n",&save);name&&nnames<256;name=strtok_r(NULL,"\n",&save)){char *match=strstr(name,frames.selection);if(!match)continue;char after=match[strlen(frames.selection)];if(after&&after!='/'&&after!=' '&&after!='#'&&after!=']')continue;if(strstr(name,"Background")||strstr(name,"WindowToken")||strstr(name,"ActivityRecord")||strstr(name,"Animation"))continue;names[nnames++]=name;}
    for(int priority=0;priority<3;priority++)for(int n=0;n<nnames&&tested<3;n++){char *name=names[n];int score=strstr(name,"SurfaceView")?0:strstr(name,"ChromeChildSurface")?1:2;if(score!=priority)continue;tested++;char values[16384];if(!framecommand(values,sizeof values,"--latency",name))continue;U64 present[128];int count=0;char *lineSave=NULL,*line=strtok_r(values,"\n",&lineSave);while((line=strtok_r(NULL,"\n",&lineSave))&&count<128){U64 desired,at,ready;if(sscanf(line,"%llu %llu %llu",&desired,&at,&ready)==3&&at>0&&at<9223372036854775807ULL)present[count++]=at;}if(!count)continue;qsort(present,(size_t)count,sizeof *present,framecompare);int layer=framelayer(0,0,(unsigned char*)name,strlen(name),2);if(layer<0)continue;FrameLayer *l=&frames.layers[layer];struct timespec mono;clock_gettime(CLOCK_MONOTONIC,&mono);U64 monoNs=(U64)mono.tv_sec*1000000000ULL+mono.tv_nsec,offset=bootns()-monoNs;if(count>=120&&l->last&&present[0]+offset>l->last)frames.loss=1;for(int i=0;i<count;i++){U64 at=present[i]+offset;if(at<frames.began||at<=l->last)continue;FrameSpan span={.kind=4,.layer=layer,.start=at,.end=at,.present=1,.jank=-1};framewrite(&span,at);}}
}
static void framestart(int seconds,const char *selection){memset(&frames,0,sizeof frames);frames.began=bootns();snprintf(frames.selection,sizeof frames.selection,"%s",selection);char file[512];path(file,sizeof file,"record.frames.csv");frames.csv=fopen(file,"w");if(frames.csv)fputs("elapsedMs,layerId,pid,appToken,displayToken,presentNs,intervalMs,appTimelineMs,expectedTimelineMs,jankMask,presentType\n",frames.csv);path(file,sizeof file,"record.trace");char id[64];char idpath[512];path(idpath,sizeof idpath,"record.id");if(readtext(idpath,id,sizeof id)){id[strcspn(id,"\r\n")]=0;int valid=strlen(id)==36;for(size_t i=0;i<strlen(id)&&valid;i++)valid=(id[i]>='0'&&id[i]<='9')||(id[i]>='a'&&id[i]<='f')||id[i]=='-';if(valid&&access("/data/misc/perfetto-traces",W_OK)==0)snprintf(file,sizeof file,"/data/misc/perfetto-traces/lighttuner-%s.pftrace",id);}snprintf(frames.trace,sizeof frames.trace,"%s",file);unlink(file);char config[512],log[512];path(config,sizeof config,"record.perfetto.cfg");path(log,sizeof log,"record.perfetto.log");FILE *f=fopen(config,"w");if(!f)return;fprintf(f,"buffers { size_kb: 2048 fill_policy: RING_BUFFER }\ndata_sources { config { name: \"android.surfaceflinger.frametimeline\" } }\nduration_ms: %d\nwrite_into_file: true\nfile_write_period_ms: 1000\nmax_file_size_bytes: 33554432\n",(seconds+1)*1000);fclose(f);if(access("/system/bin/perfetto",X_OK)==0){pid_t child=fork();if(!child){int null=open("/dev/null",O_RDONLY),output=open(log,O_CREAT|O_WRONLY|O_TRUNC,0600);if(null>=0)dup2(null,STDIN_FILENO);if(output>=0){dup2(output,STDOUT_FILENO);dup2(output,STDERR_FILENO);}execl("/system/bin/perfetto","perfetto","--txt","-c",config,"-o",file,(char*)NULL);_exit(127);}if(child>0){frames.tracePid=child;char pidpath[512];path(pidpath,sizeof pidpath,"record.perfetto.pid");FILE *pid=fopen(pidpath,"w");if(pid){fprintf(pid,"%d\n",child);fclose(pid);}}}framesummary();}
static void frameupdate(void){framepoll();if(frames.tracePid>0&&waitpid(frames.tracePid,NULL,WNOHANG)==frames.tracePid){frames.tracePid=0;char file[512];struct stat s;snprintf(file,sizeof file,"%s",frames.trace);if(!stat(file,&s)&&s.st_size>=33554432-4096)frames.capped=1;}int observed=0;for(int i=0;i<frames.nlayers;i++)if(frames.layers[i].source==1&&frames.layers[i].presented>1&&frames.layers[i].last+3000000000ULL>=bootns())observed=1;if(!observed)framelatency();framesummary();}
static void framefinish(void){frames.ended=bootns();if(frames.tracePid>0){kill(frames.tracePid,SIGINT);for(int i=0;i<20;i++){if(waitpid(frames.tracePid,NULL,WNOHANG)==frames.tracePid){frames.tracePid=0;break;}usleep(50000);}if(frames.tracePid>0){kill(frames.tracePid,SIGKILL);waitpid(frames.tracePid,NULL,0);frames.tracePid=0;frames.loss=1;}}for(int i=0;i<4;i++)framepoll();framesummary();if(frames.csv)fclose(frames.csv);char file[512];snprintf(file,sizeof file,"%s",frames.trace);unlink(file);}
